<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';import { useRoute } from 'vue-router';import { api } from '../api';import type { Project, Task, User } from '../types';import { useAuthStore } from '../stores/auth';import { ElMessage } from 'element-plus'
const route=useRoute(),auth=useAuthStore(),project=ref<Project|null>(null),tasks=ref<Task[]>([]),users=ref<User[]>([]),dialog=ref(false),form=reactive<Partial<Task>>({title:'',status:'todo',priority:'medium',progress:0,estimatedHours:0})
const id=Number(route.params.id);async function load(){project.value=await api.project(id);tasks.value=await api.projectTasks(id);users.value=await api.users()}onMounted(load);function edit(t?:Task){Object.assign(form,t??{id:undefined,projectId:id,title:'',status:'todo',priority:'medium',progress:0,estimatedHours:0});dialog.value=true}async function save(){await api.saveTask(form);dialog.value=false;ElMessage.success('任务已保存');load()}async function status(t:Task,s:string){await api.status(t.id,s,t.version);load()}
</script>
<template><div class="page" v-if="project"><div class="page-header"><div><h1 class="page-title">{{project.name}}</h1><p>{{project.code}} · {{project.status}}</p></div><el-button v-if="auth.isManager" type="primary" @click="edit()">新增任务</el-button></div><section class="card"><el-progress :percentage="Number(project.progress)"/><h3>项目看板</h3><div class="board"><div v-for="column in ['todo','in_progress','review','done']" :key="column" class="column"><strong>{{column}}</strong><div v-for="task in tasks.filter(t=>t.status===column)" :key="task.id" class="task"><b>{{task.title}}</b><span>{{task.priority}} · {{task.progress}}%</span><div><el-button v-if="task.status!=='done'" size="small" @click="status(task,task.status==='todo'?'in_progress':'done')">推进</el-button><el-button size="small" link @click="edit(task)">编辑</el-button></div></div></div></div></section><el-dialog v-model="dialog" title="任务"><el-form label-width="90"><el-form-item label="标题"><el-input v-model="form.title"/></el-form-item><el-form-item label="负责人"><el-select v-model="form.assigneeId" clearable><el-option v-for="u in users" :key="u.id" :label="u.displayName" :value="u.id"/></el-select></el-form-item><el-form-item label="优先级"><el-select v-model="form.priority"><el-option label="低" value="low"/><el-option label="中" value="medium"/><el-option label="高" value="high"/><el-option label="紧急" value="urgent"/></el-select></el-form-item><el-form-item label="预估工时"><el-input-number v-model="form.estimatedHours" :min="0"/></el-form-item><el-form-item label="执行进度"><el-slider v-model="form.progress"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<style scoped>.board{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.column{background:#f1f5f9;padding:12px;border-radius:6px;min-height:300px}.task{margin-top:10px;padding:12px;background:#fff;border-radius:5px;box-shadow:0 1px 2px #0001}.task span{display:block;color:#64748b;font-size:12px;margin:6px 0}</style>

